extern double BeginApiTrace(); extern unsigned long long ApiCpuCycles(); extern void FinishApiTrace(const char*,double,unsigned long long); struct ApiTrace { const char* n; double begin; unsigned long long cycles; ApiTrace(const char* name):n(name),begin(BeginApiTrace()),cycles(begin?ApiCpuCycles():0){} ~ApiTrace(){unsigned long long elapsed=begin?ApiCpuCycles()-cycles:0;FinishApiTrace(n,begin,elapsed);} };
HMODULE coreModule=nullptr,extModule=nullptr; bool openMode=false;
void* Resolve(const char* name,bool ext) {std::string n=name; if(openMode)n.replace(0,6,"OpenFleX"); auto p=GetProcAddress(ext?extModule:coreModule,n.c_str()); if(!p){fprintf(stderr,"MISSING %s\n",n.c_str());exit(71);}return (void*)p;}
